export const ingestRescueSnapshotBodySourceAdapterRegExp = new RegExp('^[a-z0-9]+(-[a-z0-9]+)*$');
export const ingestRescueSnapshotBodyDogsItemExternalIdMax = 200;

export const ingestRescueSnapshotBodyDogsItemNameMax = 100;

export const ingestRescueSnapshotBodyDogsItemStatusDefault = `available`;
export const ingestRescueSnapshotBodyDogsItemBreedsItemMax = 100;

export const ingestRescueSnapshotBodyDogsItemBreedsMax = 5;

export const ingestRescueSnapshotBodyDogsItemGoodWithKidsDefault = null;
export const ingestRescueSnapshotBodyDogsItemGoodWithDogsDefault = null;
export const ingestRescueSnapshotBodyDogsItemGoodWithCatsDefault = null;
export const ingestRescueSnapshotBodyDogsItemProfileUrlDefault = null;
export const ingestRescueSnapshotBodyDogsItemImageUrlDefault = null;
export const ingestRescueSnapshotBodyDogsItemBirthYearDefault = null;
export const ingestRescueSnapshotBodyDogsItemBirthYearMin = 1990;
export const ingestRescueSnapshotBodyDogsItemBirthYearMax = 2100;

export const ingestRescueSnapshotBodyDogsItemBirthMonthDefault = null;
export const ingestRescueSnapshotBodyDogsItemBirthMonthMax = 12;

export const ingestRescueSnapshotBodyDogsItemBirthDayDefault = null;
export const ingestRescueSnapshotBodyDogsItemBirthDayMax = 31;

export const ingestRescueSnapshotBodyDogsItemRescueSinceDateDefault = null;
export const ingestRescueSnapshotBodyDogsMax = 2000;



export const IngestRescueSnapshotBody = zod.strictObject({
  "capturedAt": zod.iso.datetime({"offset":true}),
  "source": zod.strictObject({
  "adapter": zod.string().regex(ingestRescueSnapshotBodySourceAdapterRegExp).describe('The finder adapter name, e.g. cardiff-dogs-home.'),
  "url": zod.url().describe('The listing page the snapshot came from.'),
  "mode": zod.enum(['live', 'fixture']).describe('live means the site was fetched; fixture means saved HTML was parsed.'),
  "adapterVersion": zod.string().optional().describe('Version of the adapter\'s parsing rules.')
}),
  "complete": zod.boolean().describe('true when the snapshot holds every dog the site lists, so absence means withdrawn. false for a partial capture; nothing is withdrawn.\n'),
  "dogs": zod.array(zod.strictObject({
  "externalId": zod.string().min(1).max(ingestRescueSnapshotBodyDogsItemExternalIdMax),
  "name": zod.string().min(1).max(ingestRescueSnapshotBodyDogsItemNameMax),
  "status": zod.enum(['available', 'reserved', 'fostered', 'on_hold']).default(ingestRescueSnapshotBodyDogsItemStatusDefault).describe('The statuses a rescue website can express. Withdrawal is inferred by absence.'),
  "age": zod.enum(['Puppy', 'Young', 'Adult', 'Senior']).describe('Puppy under 1 year, Young 1 to 3 years, Adult 3 to 8 years, Senior 8 years and over. When a birth date is known the API derives this and it takes precedence over the category the source site gave.\n'),
  "size": zod.enum(['Small', 'Medium', 'Large']),
  "gender": zod.enum(['Male', 'Female']),
  "breeds": zod.array(zod.string().min(1).max(ingestRescueSnapshotBodyDogsItemBreedsItemMax)).max(ingestRescueSnapshotBodyDogsItemBreedsMax).describe('Breed names as written on the site; the API resolves synonyms.'),
  "goodWithKids": zod.boolean().nullish().default(ingestRescueSnapshotBodyDogsItemGoodWithKidsDefault).describe('true if good with, false if not, null if the rescue has not said.'),
  "goodWithDogs": zod.boolean().nullish().default(ingestRescueSnapshotBodyDogsItemGoodWithDogsDefault).describe('true if good with, false if not, null if the rescue has not said.'),
  "goodWithCats": zod.boolean().nullish().default(ingestRescueSnapshotBodyDogsItemGoodWithCatsDefault).describe('true if good with, false if not, null if the rescue has not said.'),
  "profileUrl": zod.url().nullish().default(ingestRescueSnapshotBodyDogsItemProfileUrlDefault),
  "imageUrl": zod.url().nullish().default(ingestRescueSnapshotBodyDogsItemImageUrlDefault),
  "birthYear": zod.int().min(ingestRescueSnapshotBodyDogsItemBirthYearMin).max(ingestRescueSnapshotBodyDogsItemBirthYearMax).nullish().default(ingestRescueSnapshotBodyDogsItemBirthYearDefault),
  "birthMonth": zod.int().min(1).max(ingestRescueSnapshotBodyDogsItemBirthMonthMax).nullish().default(ingestRescueSnapshotBodyDogsItemBirthMonthDefault),
  "birthDay": zod.int().min(1).max(ingestRescueSnapshotBodyDogsItemBirthDayMax).nullish().default(ingestRescueSnapshotBodyDogsItemBirthDayDefault),
  "rescueSinceDate": zod.iso.date().nullish().default(ingestRescueSnapshotBodyDogsItemRescueSinceDateDefault)
}).describe('One dog as seen on a rescue website. Only factual, non-copyrightable data: no descriptions, no copied images. `externalId` must be stable across captures of the same dog; the dog\'s page URL slug is the usual choice.\n')).max(ingestRescueSnapshotBodyDogsMax)
}).describe('Every dog listed on a rescue\'s website at one moment.')

